ame, category, category_code sub_category, category_code, commonsku, TAX_RATE from maplemonk.final_sku_master qualify row_number() over (partition by marketplace_sku order by 1) = 1 ) p on lower(tr.Product_SKU_Code) = lower(p.skucode) ;",
